export async function listSalesPlans(
  query: SalesPlanFilterQuery,
): Promise<SalesPlanListItem[]> {
  const qs = new URLSearchParams();
  (Object.entries(query) as [string, string | number | boolean | undefined][]).forEach(([key, value]) => {
    if (value === undefined || value === '') return;
    if (key === 'locNsd' && value !== true) return;
    qs.set(key, String(value));
  });
  const suffix = qs.toString();
  const res = await apiClient.get<BffResponse<SalesPlanListItem[]>>(
    `/sales/sales-plans${suffix ? `?${suffix}` : ''}`,
  );
  return unwrap(res) ?? [];
}

export async function getSalesPlan(sttRec: string): Promise<SalesPlanDetail> {
  const res = await apiClient.get<BffResponse<SalesPlanDetail>>(
    `/sales/sales-plans/${encodeURIComponent(sttRec)}`,
  );
  return unwrap(res);
}

export async function createSalesPlan(body: SalesPlanWriteBody): Promise<SalesPlanDetail> {
  const res = await apiClient.post<BffResponse<SalesPlanDetail>>(
    '/sales/sales-plans',
    body,
  );
  return unwrap(res);
}

export async function updateSalesPlan(
  sttRec: string,
  body: SalesPlanWriteBody,
): Promise<SalesPlanDetail> {
  const res = await apiClient.put<BffResponse<SalesPlanDetail>>(
    `/sales/sales-plans/${encodeURIComponent(sttRec)}`,
    body,
  );
  return unwrap(res);
}
